import React, { useState } from 'react';
import FileUploader from '../components/FileUploader';
import Result from '../components/Result';
import axios from 'axios';

const PYTHON_URL = 'http://localhost:5000';
const JAVA_URL = 'http://localhost:8080/api';

const QuizPage = () => {
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleFileUpload = async (file) => {
        if (!file) {
            setError("Veuillez sélectionner un fichier valide.");
            return;
        }

        const validMimeTypes = ['application/pdf', 'text/plain', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        if (!validMimeTypes.includes(file.type)) {
            setError("Type de fichier non supporté. Veuillez sélectionner un fichier PDF, TXT ou DOCX.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setResult(null);

        try {
            // 1. Envoi du fichier au microservice Python
            const formData = new FormData();
            formData.append('file', file);
            
            const extractResponse = await axios.post(`${PYTHON_URL}/extract-text`, formData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });

            // 2. Envoi du texte extrait au backend Java
            const quizResponse = await axios.post(`${JAVA_URL}/quizzes/generate`, extractResponse.data.extractedText, {
                headers: { 'Content-Type': 'text/plain' }
            });

            setResult(quizResponse.data);
        } catch (error) {
            setError("Échec de la génération du quiz. Veuillez réessayer.");
            console.error('Erreur:', error.response?.data || error);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="quiz-page">
            <h1>Générer un Quiz</h1>
            
            <FileUploader 
                onUpload={handleFileUpload} 
                disabled={isLoading} 
                accept=".pdf,.txt,.docx" 
            />
            
            {isLoading && (
                <div className="loading-container">
                    <p className="loading-message">Génération du quiz en cours...</p>
                    <div className="loading-spinner"></div>
                </div>
            )}
            
            {error && <p className="error-message">{error}</p>}
            {result && <Result data={result} />}
        </div>
    );
};

export default QuizPage;
